-- 0020_add_oauth_provider — generated by `pnpm gen:migration`. Additive and reversible (ocs-db-migration);
-- never edit a migration once it is on main (CI pr-rules).
-- D-33 / D-07: OCS as an OAuth 2.1 provider, so AI clients (ChatGPT, Claude, any MCP client) sign in as the
-- person and act with that person's permissions. Tables of @better-auth/oauth-provider 1.7.23, transcribed from
-- better-auth's own getAuthTables() output (names camelCase, quoted, as in 0002). Like the other login tables
-- they live in schema `auth`, reachable only by role ocs_auth: tokens and client secrets are credentials.
-- Ids are UUID v7 (createAuth generateId). Lists (scopes, redirect URIs…) are JSON text: better-auth's postgres
-- adapter stores string[] as JSON strings (supportsArrays: false) and json natively (jsonb).

-- A registered AI client (dynamic client registration or set up by an admin).
CREATE TABLE auth."oauthClient" (
  id                                 uuid PRIMARY KEY,
  "clientId"                         text NOT NULL UNIQUE,
  "clientSecret"                     text,
  "clientDiscoveryId"                text,
  disabled                           boolean DEFAULT false,
  "skipConsent"                      boolean,
  "enableEndSession"                 boolean,
  "subjectType"                      text,
  scopes                             text,
  "clientCredentialsScopes"          text DEFAULT '[]',
  "userId"                           uuid REFERENCES auth."user" (id),
  "createdAt"                        timestamptz,
  "updatedAt"                        timestamptz,
  name                               text,
  uri                                text,
  icon                               text,
  contacts                           text,
  tos                                text,
  policy                             text,
  "softwareId"                       text,
  "softwareVersion"                  text,
  "softwareStatement"                text,
  "redirectUris"                     text NOT NULL,
  "postLogoutRedirectUris"           text,
  "backchannelLogoutUri"             text,
  "backchannelLogoutSessionRequired" boolean,
  "tokenEndpointAuthMethod"          text,
  "applicationType"                  text,
  jwks                               text,
  "jwksUri"                          text,
  "grantTypes"                       text,
  "responseTypes"                    text,
  "requirePKCE"                      boolean,
  "dpopBoundAccessTokens"            boolean DEFAULT false,
  "referenceId"                      text,
  metadata                           jsonb
);
CREATE INDEX oauth_client_user_id ON auth."oauthClient" ("userId");

-- A protected resource (the OCS MCP endpoint) and which clients may ask for it.
CREATE TABLE auth."oauthResource" (
  id                              uuid PRIMARY KEY,
  identifier                      text NOT NULL UNIQUE,
  name                            text NOT NULL,
  "accessTokenTtl"                integer,
  "refreshTokenTtl"               integer,
  "signingAlgorithm"              text,
  "signingKeyId"                  text,
  "allowedScopes"                 text,
  "customClaims"                  jsonb,
  "dpopBoundAccessTokensRequired" boolean DEFAULT false,
  disabled                        boolean DEFAULT false,
  "createdAt"                     timestamptz,
  "updatedAt"                     timestamptz,
  "policyVersion"                 integer DEFAULT 1,
  metadata                        jsonb
);

CREATE TABLE auth."oauthClientResource" (
  id           uuid PRIMARY KEY,
  "clientId"   text NOT NULL REFERENCES auth."oauthClient" ("clientId") ON DELETE CASCADE,
  "resourceId" text NOT NULL REFERENCES auth."oauthResource" (identifier) ON DELETE CASCADE,
  metadata     jsonb,
  "createdAt"  timestamptz
);
CREATE INDEX oauth_client_resource_client ON auth."oauthClientResource" ("clientId");

CREATE TABLE auth."oauthRefreshToken" (
  id                         uuid PRIMARY KEY,
  token                      text NOT NULL UNIQUE,
  "clientId"                 text NOT NULL REFERENCES auth."oauthClient" ("clientId"),
  "sessionId"                uuid REFERENCES auth.session (id) ON DELETE SET NULL,
  "userId"                   uuid NOT NULL REFERENCES auth."user" (id),
  "referenceId"              text,
  "authorizationCodeId"      text,
  resources                  text,
  "requestedUserInfoClaims"  text,
  "expiresAt"                timestamptz,
  "createdAt"                timestamptz,
  revoked                    timestamptz,
  "rotatedAt"                timestamptz,
  "rotationReplayResponse"   text,
  "rotationReplayExpiresAt"  timestamptz,
  "authTime"                 timestamptz,
  confirmation               jsonb,
  scopes                     text NOT NULL
);
CREATE INDEX oauth_refresh_token_user ON auth."oauthRefreshToken" ("userId");
CREATE INDEX oauth_refresh_token_client ON auth."oauthRefreshToken" ("clientId");

CREATE TABLE auth."oauthAccessToken" (
  id                         uuid PRIMARY KEY,
  token                      text UNIQUE,
  "clientId"                 text NOT NULL REFERENCES auth."oauthClient" ("clientId"),
  "sessionId"                uuid REFERENCES auth.session (id) ON DELETE SET NULL,
  "userId"                   uuid REFERENCES auth."user" (id),
  "referenceId"              text,
  "authorizationCodeId"      text,
  resources                  text,
  "requestedUserInfoClaims"  text,
  "refreshId"                uuid REFERENCES auth."oauthRefreshToken" (id),
  "expiresAt"                timestamptz,
  "createdAt"                timestamptz,
  revoked                    timestamptz,
  confirmation               jsonb,
  scopes                     text NOT NULL
);
CREATE INDEX oauth_access_token_user ON auth."oauthAccessToken" ("userId");
CREATE INDEX oauth_access_token_client ON auth."oauthAccessToken" ("clientId");

-- The person's consent: which client may act for them, with which scopes.
CREATE TABLE auth."oauthConsent" (
  id                        uuid PRIMARY KEY,
  "clientId"                text NOT NULL REFERENCES auth."oauthClient" ("clientId"),
  "userId"                  uuid REFERENCES auth."user" (id),
  "referenceId"             text,
  resources                 text,
  "requestedUserInfoClaims" text,
  scopes                    text NOT NULL,
  "createdAt"               timestamptz,
  "updatedAt"               timestamptz
);
CREATE INDEX oauth_consent_user ON auth."oauthConsent" ("userId");

-- Replay protection for client assertions (private_key_jwt).
CREATE TABLE auth."oauthClientAssertion" (
  id          text PRIMARY KEY,
  "expiresAt" timestamptz NOT NULL
);

-- Only better-auth (ocs_auth) touches these: credentials, like auth.session. DELETE only where the plugin removes
-- credentials (revoked or replaced tokens, withdrawn consent); clients are disabled, never deleted.
GRANT SELECT, INSERT, UPDATE ON auth."oauthClient", auth."oauthResource", auth."oauthClientResource",
  auth."oauthRefreshToken", auth."oauthAccessToken", auth."oauthConsent", auth."oauthClientAssertion" TO ocs_auth;
GRANT DELETE ON auth."oauthAccessToken", auth."oauthRefreshToken", auth."oauthConsent" TO ocs_auth;

ALTER TABLE auth."oauthClient" ENABLE ROW LEVEL SECURITY;
CREATE POLICY oauth_client_auth ON auth."oauthClient" FOR ALL TO ocs_auth USING (true) WITH CHECK (true);
ALTER TABLE auth."oauthResource" ENABLE ROW LEVEL SECURITY;
CREATE POLICY oauth_resource_auth ON auth."oauthResource" FOR ALL TO ocs_auth USING (true) WITH CHECK (true);
ALTER TABLE auth."oauthClientResource" ENABLE ROW LEVEL SECURITY;
CREATE POLICY oauth_client_resource_auth ON auth."oauthClientResource" FOR ALL TO ocs_auth USING (true) WITH CHECK (true);
ALTER TABLE auth."oauthRefreshToken" ENABLE ROW LEVEL SECURITY;
CREATE POLICY oauth_refresh_token_auth ON auth."oauthRefreshToken" FOR ALL TO ocs_auth USING (true) WITH CHECK (true);
ALTER TABLE auth."oauthAccessToken" ENABLE ROW LEVEL SECURITY;
CREATE POLICY oauth_access_token_auth ON auth."oauthAccessToken" FOR ALL TO ocs_auth USING (true) WITH CHECK (true);
ALTER TABLE auth."oauthConsent" ENABLE ROW LEVEL SECURITY;
CREATE POLICY oauth_consent_auth ON auth."oauthConsent" FOR ALL TO ocs_auth USING (true) WITH CHECK (true);
ALTER TABLE auth."oauthClientAssertion" ENABLE ROW LEVEL SECURITY;
CREATE POLICY oauth_client_assertion_auth ON auth."oauthClientAssertion" FOR ALL TO ocs_auth USING (true) WITH CHECK (true);
